+/// Parte C++ della primitiva rw_downgrade()
+extern "C" void c_rw_downgrade(natl rw)
+{
+	if (!rw_valido(rw)) {
+		flog(LOG_WARN, "rw_downgrade(%d): rwlock non valido", rw);
+		c_abort_p();
+		return;
+	}
+
+	des_rw *r = &array_desrw[rw];
+	des_proc_rw *rp = rw_proc_find(r);
+
+	if (!rp) {
+		flog(LOG_WARN, "rw_downgrade(%d): processo non possiede lock su rw", rw);
+		c_abort_p();
+		return;
+	}
+
+	if (rp->state == RW_UPGRADED) {
+		r->writer = 0;
+		rp->state = RW_READER;
+		r->nreaders++;
